css:
/* General layout */
body {
    font-family: Courier, monospace;
    margin: 0;
    padding: 0;
    background: #fff;
}

table, tr, td {
    margin: 0 !important;
    padding: 0;
    border-spacing: 0;
    border-collapse: collapse;
}

/* Main outer table */
.main-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    table-layout: fixed;
}

.main-table td,
.main-table th {
    padding: 0;
}

/* Left: 2x2 Grid Area */
.left-40 {
    width: 70% !important;
    vertical-align: top;
    font-size:8px;
    font-family: Courier, monospace;
}

/* Right: Image + Text */
.right-20 {
    width: 30% !important;
    vertical-align: middle;
}

/* Inner 2x2 table */
.grid-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 10 5px;
    margin-right:-10px;
    padding:0px;
}

.grid-cell {
    margin-top:-7px;
    width: 50%;
    height: 60px;
    border: 1px solid #ccc;
    text-align: center;
    vertical-align: middle;
    border-radius: 5px;
}

/* Nested table for image + text */
.nested-right-table {
    width: 100%;
    table-layout: fixed;
    margin:5px 0px 0px -7px !important;
}

.image-cell {
    width: 60%;
}

.image-cell img {
    object-fit: cover;
}

.text-cell {
    width: 40%;
    font-size: 9px;
    font-family: sans-serif;
    line-height:1.5;
    color: #333;
    vertical-align: middle;
    padding-left: 10px;
}

.section-combined-box {
    display: flex;
    border: 1.5px solid #888;
    border-radius: 7px 7px 0 0;
    overflow: hidden;
    height: 32px;
    font-size: 10px;
    font-family: Courier, monospace;
    text-align: center;
}
.separate-combined-box {
    display: flex;
    border: 1.5px solid #888;
    border-radius: 0px 0px 7px 7px;
    overflow: hidden;
    height: 32px;
    font-size: 10px;
    font-family: Courier, monospace;
    text-align: center;
    margin-bottom:8px;
}

.section-inner {
    flex: 1;
    line-height: 32px;
    padding: 0 8px;
    border-right: 1px solid transparent; /* Optional visual gap without border color */
}

.section-inner:last-child {
    border-right: none;
}

/* Section box (seems unused but kept if relevant elsewhere) */
.section-box {
    border: 1.5px solid #888;
    height: 32px;
    border-radius: 7px 7px 0px 0px;
}

/* Consolidated Custom Data Table (for items) */
.custom-table {
    border: 1.3px solid #9d8383 !important;
    border-radius: 15px !important;
    width: 100%;
    height: 20vh; /* This height applies to screen, overridden for print */
    border-collapse: separate !important;
    overflow: hidden;
    display: table; /* Necessary for table-related properties to work */
    table-layout: fixed; /* Keep fixed layout for consistent column widths */
    position: relative; /* If used for positioning internal elements */
    padding:10px;
}

.custom-table th,
.custom-table td {
    padding: 10px;
    text-align: left;
    font-size: 11px;
    border: none;
    font-family: Courier, monospace;
}

.custom-table th {
    font-size: 12px;
    color: black;
    border-bottom: 1px solid #9d8383;
    align-content:center;
}

.custom-table thead {
    border-bottom: 2px solid #9d8383; /* This applies to screen */
    display: table-header-group; /* Reset to default table display groups for screen */
}

.custom-table tbody {
    display: table-row-group; /* Reset to default table display groups for screen */
    height: 100%; /* This height applies to screen */
    vertical-align: top;
}

.custom-table tfoot {
    display: table-footer-group; /* Reset to default table display groups for screen */
    margin-top: auto;
}


.custom-table-2 {
    border: 1.3px solid #9d8383;
    border-radius: 10px;
    margin-top: 5px !important;
    width: 100%;
    border-collapse: separate;
    overflow: hidden;
    font-family: Arial, sans-serif;
    padding: 10px 0px 0px 0px;
}

.custom-table-2 th,
.custom-table-2 td {
    color: black;
    font-size: 12px;
    text-align: center;
    padding: 8px 12px;
}

.custom-table-2 thead th {
    height: 10px;
}

/* Print format padding override (if .print-format class is used on print content) */
.print-format td,
.print-format th {
    padding: 1px !important;
}

/* Bottom Info Row: full width */
.bottom-info-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: 5px;
}

.bottom-info-table td {
    vertical-align: middle;
    padding: 10px;
}

/* Left: Warning */
.invalid-purchase {
    width: 40%;
    text-align: center;
    font-size: 10px;
    align-content: center;
    background-color: transparent !important;
}
.invalid-purchase pre {
    background-color: transparent !important;
    font-family: Courier, monospace;
    margin: 0;
    padding: 0;
    white-space: pre;
    text-align: center;
    border:none;
    font-size: 10px;
    line-height: 1.1;
}

/* Middle: QR */
.qr-cell {
    width: 20%;
    text-align: center;
}

.qr-cell img {
    width: 80px;
    height: 150px;
    object-fit: contain;
}

/* Right: Total */
.grand-total {
    width: 40%;
    font-family: Courier, monospace;
    align-content: center;
    font-size: 11px;
    align-content: baseline;
}

.grand-total .amount {
    font-size: 11px;
    font-family: Courier, monospace;
    color: #000;
    align-content:center;
}
/* QR Column */
.qr-cell {
    width: 20%;
    text-align: center;
    vertical-align: middle;
}

.qr-wrapper {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.qr-wrapper img {
    width: 80px;
    height: 80px;
    object-fit: contain;
    margin-bottom: 5px;
}

.qr-caption {
    font-size: 11px;
    color: #333;
    text-align: center;
}

/* --- Print Styles --- */
@media print{
    .nested-right-table {
    margin:0px 0px 5px 5px !important;
}
.print-page-footer {
        position: fixed; /* Sticks the footer to the viewport */
        bottom: 0;       /* Aligns it to the bottom of the viewport */
        left: 0;         /* Aligns it to the left edge of the viewport */
        width: 100%;     /* Makes it span the full width of the viewport */
        background-color: #fff; /* Ensures no content shows through */
        padding: 10px;   /* Padding around the footer content */
        box-sizing: border-box; /* Includes padding in the width calculation */
        text-align: center;
        font-size: 11px;
        border: none; /* Single border around the entire footer container */
        border-radius: 0px; /* Apply border-radius to the container */
    }

    .print-page-footer .custom-table-2 {
        border: 1.3px solid #9d8383;; /* Remove border from the inner table */
        border-radius: 10px; /* Remove border-radius from the inner table */
        margin-top: 0; /* Adjust margin as needed */
        padding-top: 10px;
        width:100%;
    }

    .print-page-footer .custom-table-2 th,
    .print-page-footer .custom-table-2 td {
        border: none; /* Remove internal cell borders */
    }

    .print-page-footer .custom-table-2 thead th {
        border-bottom: none; /* Remove bottom border from header cells */
    }
    .grid-table {
        /* This creates horizontal and vertical spacing between cells. */
        /* The first value is horizontal spacing, the second is vertical. */
        border-spacing: 10px 5px; 
        margin-right: 0; /* Ensures no unintended margin interferes with spacing */
    }

    .grid-cell {
        /* You may need to adjust or remove existing margins/paddings */
        margin-top: -7px; /* Keep if needed for positioning within the overall layout */
        /* ... other existing grid-cell styles ... */
    }
}
